solution.forth.zig:
const std = @import("std");

const Builtin = enum { add, sub, mul, div, dup, drop, swap, over };
const Op = union(enum) { number: i64, builtin: Builtin };
fn resolve(allocator: std.mem.Allocator, word: []const u8, definitions: std.StringHashMap([]const Op), ops: *std.array_list.Managed(Op)) !void {
    const lower = try allocator.alloc(u8, word.len);
    _ = std.ascii.lowerString(lower, word);
    if (std.fmt.parseInt(i64, lower, 10)) |number| {
        try ops.append(.{ .number = number });
        return;
    } else |_| {}
    if (definitions.get(lower)) |body| {
        try ops.appendSlice(body);
        return;
    }
    const names = [_][]const u8{ "+", "-", "*", "/", "dup", "drop", "swap", "over" };
    for (names, 0..) |name, i| if (std.mem.eql(u8, lower, name)) {
        try ops.append(.{ .builtin = @fromBackingInt(@intCast(i)) });
        return;
    };
    return error.UndefinedOperation;
}
fn execute(ops: []const Op, stack: *std.array_list.Managed(i64)) !void {
    for (ops) |op| switch (op) {
        .number => |n| try stack.append(n),
        .builtin => |b| {
            const needed: usize = if (b == .dup or b == .drop) 1 else 2;
            if (stack.items.len < needed) return error.StackUnderflow;
            const n = stack.items.len;
            const top = stack.items[n - 1];
            switch (b) {
                .dup => try stack.append(top),
                .drop => {
                    _ = stack.pop();
                },
                .swap => {
                    stack.items[n - 1] = stack.items[n - 2];
                    stack.items[n - 2] = top;
                },
                .over => try stack.append(stack.items[n - 2]),
                else => {
                    const left = stack.items[n - 2];
                    const value = switch (b) {
                        .add => left + top,
                        .sub => left - top,
                        .mul => left * top,
                        .div => if (top == 0) return error.DivisionByZero else @divTrunc(left, top),
                        else => unreachable,
                    };
                    stack.items[n - 2] = value;
                    _ = stack.pop();
                },
            }
        },
    };
}
pub fn evaluate(allocator: std.mem.Allocator, input: []const []const u8) ![]i64 {
    var arena = std.heap.ArenaAllocator.init(allocator);
    defer arena.deinit();
    const scratch = arena.allocator();
    var definitions = std.StringHashMap([]const Op).init(scratch);
    var stack = std.array_list.Managed(i64).init(allocator);
    errdefer stack.deinit();
    for (input) |line| {
        var tokens = std.mem.tokenizeAny(u8, line, " \t\r\n");
        while (tokens.next()) |word| {
            if (std.mem.eql(u8, word, ":")) {
                const raw = tokens.next() orelse return error.IllegalDefinition;
                const name = try scratch.alloc(u8, raw.len);
                _ = std.ascii.lowerString(name, raw);
                if (std.fmt.parseInt(i64, name, 10)) |_| return error.IllegalDefinition else |_| {}
                var body = std.array_list.Managed(Op).init(scratch);
                var ended = false;
                while (tokens.next()) |token| {
                    if (std.mem.eql(u8, token, ";")) {
                        ended = true;
                        break;
                    }
                    try resolve(scratch, token, definitions, &body);
                }
                if (!ended) return error.IllegalDefinition;
                try definitions.put(name, try body.toOwnedSlice());
            } else {
                var ops = std.array_list.Managed(Op).init(scratch);
                try resolve(scratch, word, definitions, &ops);
                try execute(ops.items, &stack);
            }
        }
    }
    return stack.toOwnedSlice();
}

