const std = @import("std");
const t = std.testing;
const a = t.allocator;
const m = @import("forth.zig");
test "test_parsing_and_numbers_numbers_just_get_pushed_onto_the_stack" {
    const result = try m.evaluate(a, &.{"1 2 3 4 5"});
    defer a.free(result);
    try t.expectEqualSlices(i64, &.{ 1, 2, 3, 4, 5 }, result);
}
test "test_parsing_and_numbers_pushes_negative_numbers_onto_the_stack" {
    const result = try m.evaluate(a, &.{"-1 -2 -3 -4 -5"});
    defer a.free(result);
    try t.expectEqualSlices(i64, &.{ -1, -2, -3, -4, -5 }, result);
}
test "test_addition_can_add_two_numbers" {
    const result = try m.evaluate(a, &.{"1 2 +"});
    defer a.free(result);
    try t.expectEqualSlices(i64, &.{3}, result);
}
test "test_addition_errors_if_there_is_nothing_on_the_stack" {
    try t.expectError(error.StackUnderflow, m.evaluate(a, &.{"+"}));
}
test "test_addition_errors_if_there_is_only_one_value_on_the_stack" {
    try t.expectError(error.StackUnderflow, m.evaluate(a, &.{"1 +"}));
}
test "test_addition_more_than_two_values_on_the_stack" {
    const result = try m.evaluate(a, &.{"1 2 3 +"});
    defer a.free(result);
    try t.expectEqualSlices(i64, &.{ 1, 5 }, result);
}
test "test_subtraction_can_subtract_two_numbers" {
    const result = try m.evaluate(a, &.{"3 4 -"});
    defer a.free(result);
    try t.expectEqualSlices(i64, &.{-1}, result);
}
test "test_subtraction_errors_if_there_is_nothing_on_the_stack" {
    try t.expectError(error.StackUnderflow, m.evaluate(a, &.{"-"}));
}
test "test_subtraction_errors_if_there_is_only_one_value_on_the_stack" {
    try t.expectError(error.StackUnderflow, m.evaluate(a, &.{"1 -"}));
}
test "test_subtraction_more_than_two_values_on_the_stack" {
    const result = try m.evaluate(a, &.{"1 12 3 -"});
    defer a.free(result);
    try t.expectEqualSlices(i64, &.{ 1, 9 }, result);
}
test "test_multiplication_can_multiply_two_numbers" {
    const result = try m.evaluate(a, &.{"2 4 *"});
    defer a.free(result);
    try t.expectEqualSlices(i64, &.{8}, result);
}
test "test_multiplication_errors_if_there_is_nothing_on_the_stack" {
    try t.expectError(error.StackUnderflow, m.evaluate(a, &.{"*"}));
}
test "test_multiplication_errors_if_there_is_only_one_value_on_the_stack" {
    try t.expectError(error.StackUnderflow, m.evaluate(a, &.{"1 *"}));
}
test "test_multiplication_more_than_two_values_on_the_stack" {
    const result = try m.evaluate(a, &.{"1 2 3 *"});
    defer a.free(result);
    try t.expectEqualSlices(i64, &.{ 1, 6 }, result);
}
test "test_division_can_divide_two_numbers" {
    const result = try m.evaluate(a, &.{"12 3 /"});
    defer a.free(result);
    try t.expectEqualSlices(i64, &.{4}, result);
}
test "test_division_performs_integer_division" {
    const result = try m.evaluate(a, &.{"8 3 /"});
    defer a.free(result);
    try t.expectEqualSlices(i64, &.{2}, result);
}
test "test_division_errors_if_dividing_by_zero" {
    try t.expectError(error.DivisionByZero, m.evaluate(a, &.{"4 0 /"}));
}
test "test_division_errors_if_there_is_nothing_on_the_stack" {
    try t.expectError(error.StackUnderflow, m.evaluate(a, &.{"/"}));
}
test "test_division_errors_if_there_is_only_one_value_on_the_stack" {
    try t.expectError(error.StackUnderflow, m.evaluate(a, &.{"1 /"}));
