test "test_combined_arithmetic_multiplication_and_division" {
    const result = try m.evaluate(a, &.{"2 4 * 3 /"});
    defer a.free(result);
    try t.expectEqualSlices(i64, &.{2}, result);
}
test "test_combined_arithmetic_multiplication_and_addition" {
    const result = try m.evaluate(a, &.{"1 3 4 * +"});
    defer a.free(result);
    try t.expectEqualSlices(i64, &.{13}, result);
